	KINDOF_TRANSPORT = 21
};

// ?doCreateReinforcements@ScriptActions@@IAEXABVAsciiString@@0_N@Z
void ScriptActions::doCreateReinforcements(const AsciiString &team, const AsciiString &waypoint, Bool useUnit)
{
	TeamPrototype *theTeamProto = TheScriptEngine->getTeamPrototypeNamed(team);
	Coord3D destination;
	Bool needToMoveToDestination = false;
	Bool adjustToPathable = false;
	if (useUnit)
	{
		Object *unit = TheScriptEngine->getUnitNamedByValue(waypoint);
		if (!unit)
			return;
		destination = *unit->getPosition();
		if (unit->isKindOf((KindOfType)KINDOF_REINFORCE_ADJUST))
			adjustToPathable = true;
	}
	else
	{
		Waypoint *way = TheTerrainLogic->getWaypointByName(waypoint);
		if (!way)
			return;
		destination = *way->getLocation();
	}
	if (!theTeamProto)
		return;

	const TeamTemplateInfo *pInfo = theTeamProto->getTemplateInfo();
	Coord3D origin = destination;
	Waypoint *way = TheTerrainLogic->getWaypointByName(pInfo->m_startReinforceWaypoint);
	if (way)
	{
		origin = *way->getLocation();
		if (origin.x != destination.x || origin.y != destination.y)
			needToMoveToDestination = true;
	}

	Team *theTeam = TheTeamFactory->createInactiveTeam(theTeamProto->getOwnerName(), theTeamProto->getName());
	if (!theTeam)
		return;

	const ThingTemplate *transportTemplate = 0;
	Object *transport = 0;
	if (!isEmptyString(pInfo->m_transportUnitType))
	{
		transportTemplate = TheThingFactory->findTemplate(pInfo->m_transportUnitType);
		if (transportTemplate)
		{
			transport = TheThingFactory->newObject(transportTemplate, theTeam, ObjectStatusMaskType(), 0);
			if (transport)
			{
				transport->setPosition(&origin);
				transport->setOrientation(0.0f);
				((Bfme5WalkOwner *)transport)->bfmeNotifyAll();
			}
		}
	}

	int transportCount = 1;
	int i, j;
	for (i = 0; i < pInfo->m_numUnitsInfo; i++)
	{
		const ThingTemplate *unitTemplate = TheThingFactory->findTemplate(pInfo->m_unitsInfo[i].unitThingName);
		Coord3D pos = origin;
		if (unitTemplate && theTeam)
		{
			Object *obj = 0;
			for (j = 0; j < pInfo->m_unitsInfo[i].maxUnits; j++)
			{
				obj = TheThingFactory->newObject(unitTemplate, theTeam, ObjectStatusMaskType(), 0);
				if (obj)
				{
					pos.x = origin.x + 2.25 * j * obj->getMajorRadius();
					if (adjustToPathable && !needToMoveToDestination)
					{
						AIUpdateInterface *ai = obj->getAIUpdateInterface();
						if (ai)
						{
							TheAI->pathfinder()->adjustDestination(obj, ai->getLocomotorSet(), &pos, 0);
							TheAI->pathfinder()->updateGoal(obj, &pos, TheTerrainLogic->getLayerForDestination(obj, &pos),
								"F:\\bfme\\Code\\gameengine\\Source\\GameLogic\\ScriptEngine\\ScriptActions.cpp", 0x3b3);
						}
					}
					pos.z = TheTerrainLogic->getGroundHeight(pos.x, pos.y);
					obj->setPosition(&pos);
					obj->setOrientation(0.0f);
					((Bfme5WalkOwner *)obj)->bfmeNotifyAll();
				}
			}
			if (obj)
				pos.y += 2 * obj->getMajorRadius();
		}
		origin.y = pos.y;
	}

	origin = destination;
	if (pInfo->m_teamStartsFull)
	{
		EntriesVec vecOfUnits;
		SpacesVec vecOfTransports;
		for (DLINK_ITERATOR<Object> iter = theTeam->iterate_TeamMemberList(); !iter.done(); iter.advance())
		{
			Object *obj = iter.cur();
			if (!obj)
				continue;
			if (obj == transport)
				continue;
			if (obj->getTemplate()->isKindOf(KINDOF_TRANSPORT))
			{
				ContainModuleInterface *contain = obj->getContain();
				if (contain)
					vecOfTransports.push_back(_STL::make_pair(obj->getID(), contain->getContainMax()));
			}
			else
			{
				int slots = obj->getTransportSlotCount();
				if (slots == 0)
					slots = 0x7fffff;
				vecOfUnits.push_back(_STL::make_pair(obj->getID(), (unsigned int)slots));
			}
		}

		PartitionSolver partition(vecOfUnits, vecOfTransports, PREFER_FAST_SOLUTION);
		partition.solve();
		SolutionVec solution = partition.getSolution();
		for (int k = 0; k < solution.size(); ++k)
		{
			Object *unit = TheGameLogic->findObjectByID(solution[k].first);
			Object *trans = TheGameLogic->findObjectByID(solution[k].second);
			if (!unit || !trans)
				continue;
			ContainModuleInterface *contain = trans->getContain();
			if (contain)
				contain->addToContain(unit);
		}
	}

	if (transport)
	{
		ContainModuleInterface *contain = transport->getContain();
		if (contain)
		{
			for (DLINK_ITERATOR<Object> iter = theTeam->iterate_TeamMemberList(); !iter.done(); iter.advance())
			{
				Object *obj = iter.cur();
				if (!obj)
					continue;
				if (transport && obj->getTemplate()->isEquivalentTo(transport->getTemplate()))
					continue;
				if (obj->getContainedBy())
					continue;
				Coord3D pos = origin;
				pos.z = TheTerrainLogic->getGroundHeight(pos.x, pos.y);
				if (transport)
					pos.x += transportCount * transport->getMajorRadius();
				if (contain->isValidContainerFor(obj, false))
				{
					if (!contain->isValidContainerFor(obj, true))
					{
						transport = TheThingFactory->newObject(transportTemplate, theTeam, ObjectStatusMaskType(), 0);
						if (transport)
						{
							transportCount++;
							transport->setPosition(&pos);
							transport->setOrientation(0.0f);
							contain = transport->getContain();
							((Bfme5WalkOwner *)transport)->bfmeNotifyAll();
						}
					}
					contain->addToContain(obj);
				}
			}
		}
	}

	if (transport)
	{
		for (DLINK_ITERATOR<Object> iter = theTeam->iterate_TeamMemberList(); !iter.done(); iter.advance())
		{
			Object *obj = iter.cur();
			if (!obj)
				continue;
			AIUpdateInterface *ai = obj->getAIUpdateInterface();
			if (obj->getTemplate()->isEquivalentTo(transport->getTemplate()))
			{
				if (pInfo->m_transportsExit)
				{
					if (ai)
						ai->m_command.aiMoveToAndEvacuateAndExit(&destination, CMD_FROM_SCRIPT);
				}
				else
				{
					if (ai)
						ai->m_command.aiMoveToAndEvacuate(&destination, CMD_FROM_SCRIPT);
				}
			}
			else if (!obj->isDisabledHeld())
			{
				if (ai)
					ai->m_command.aiMoveToPosition(&destination, CMD_FROM_SCRIPT);
			}
		}
	}
	else
	{
		theTeam->setActive();
		if (needToMoveToDestination)
		{
			AIGroup *theGroup = TheAI->createGroup();
			if (theGroup)
			{
				theTeam->getTeamAsAIGroup(theGroup);
				Rva0015A190Packet packet;
				packet.m_position = &destination;
				packet.m_flag = false;
				packet.m_value08 = 0;
				packet.m_value0C = 0;
				((Rva0015A190Owner *)theGroup)->applyPacket(&packet, CMD_FROM_SCRIPT);
			}
		}
	}
}
